    {
      "target_id": "t1",
      "policy_source_id": "q13",
      "policy_quote": "After user confirmation, the order status will be changed to 'exchange requested' (or in this case, 'pending (items modified)'), and the user will receive an email regarding how to return items (or in this case, the refund process).",
      "requirement": "The assistant must ensure that the user is informed about the refund process after modifying the order items, even though no new order is placed."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q10",
      "policy_quote": "You should not make up any information or knowledge or procedures not provided by the user or the tools, or give subjective recommendations or comments.",
      "requirement": "The assistant must only use information provided by the user or the tools and must not make assumptions or provide unsupported recommendations."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q10",
      "policy_quote": "You should at most make one tool call at a time, and if you take a tool call, you should not respond to the user at the same time.",
      "requirement": "The assistant must not respond to the user while making a tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q10",
      "policy_quote": "You can only help one user per conversation (but you can handle multiple requests from the same user), and must deny any requests for tasks related to any other user.",
      "requirement": "The assistant must ensure that the action is taken only for the authenticated user and not for any other user."
    }
  ]
